-- Adds the first Tree lesson: "Tree Basics" (section: Trees). Mirrors the
-- structure and pedagogy of V8's Linked List Basics lesson — same incremental
-- reveal (whole picture, then piece by piece), same bilingual tone, same visual
-- vocabulary (visual-box / node-3d / animate-bounce-subtle). Tree diagrams use an
-- absolutely-positioned canvas (SVG lines under HTML node circles) since the
-- existing chain-based visual-builder only models linear (linked-list-style)
-- structures, not branching ones.

INSERT INTO lessons (id, ordinal, icon, title_en, title_ar, description_en, description_ar, section_en, section_ar, category_en, category_ar) VALUES (6, 5, $q$🌳$q$, $q$Tree Basics$q$, $q$أساسيات الـ Tree$q$, $q$Root, Node, Edge, Parent, Child, and Leaf — the core building blocks of a Tree, plus how height and levels are measured.$q$, $q$Root و Node و Edge و Parent و Child و Leaf — أساسيات فكرة الـ Tree، وإزاي بنقيس الـ Height والـ Levels.$q$, $q$Trees$q$, $q$الأشجار$q$, $q$Fundamentals$q$, $q$الأساسيات$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (6, 0, $q$Data Structures &amp; Algorithms$q$, $q$هياكل البيانات والخوارزميات$q$, $q$Tree$q$, $q$Tree$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto"><div class="relative mx-auto w-[340px] h-[270px]"><div class="absolute left-[170px] top-[70px] origin-left rotate-[131.76deg] w-[112.6px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[170px] top-[70px] origin-left rotate-[48.24deg] w-[112.6px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[115.46deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[64.54deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[170px] top-[70px] w-14 h-14 rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d text-lg">A</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[95px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">B</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[245px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">C</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[55px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">D</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[135px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">E</div></div></div>$q$, $q$<p>Look at the picture above &mdash; that <strong>is</strong> a Tree.</p><p>We're going to break it into pieces, one at a time &mdash; just like we did with the Linked List.</p>$q$, $q$<p>بص على الرسمة اللي فوق &mdash; دي <strong>Tree</strong>.</p><p>هنفهمها جزء جزء، بالظبط زي ما عملنا مع الـ Linked List.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (6, 1, $q$The pieces$q$, $q$الأجزاء$q$, $q$How many parts do we have?$q$, $q$عندنا كام حاجة؟$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto"><div class="relative mx-auto w-[340px] h-[270px]"><div class="absolute left-[170px] top-[70px] origin-left rotate-[131.76deg] w-[112.6px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[170px] top-[70px] origin-left rotate-[48.24deg] w-[112.6px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[115.46deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[64.54deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[170px] top-[70px] w-14 h-14 rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d text-lg">A</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[95px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">B</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[245px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">C</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[55px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">D</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[135px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">E</div></div></div>$q$, $q$<p>We have 5 nodes on screen, connected by lines. Every one of them is either a:</p><ul class="list-disc list-inside space-y-1 my-3"><li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Root</code></li><li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Parent</code></li><li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Child</code></li><li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Leaf</code></li></ul><p>But here's the catch: <strong>not every node is the same.</strong> Only one has no parent, and some have no children at all.</p>$q$, $q$<p>عندنا 5 Nodes على الشاشة، متوصلة بخطوط. كل واحدة فيهم إما:</p><ul class="list-disc list-inside space-y-1 my-3"><li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Root</code></li><li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Parent</code></li><li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Child</code></li><li><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Leaf</code></li></ul><p>لكن الحقيقة: <strong>مش كل Node زي التانية.</strong> واحدة بس مالهاش Parent، وفيه Nodes مالهاش Children خالص.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (6, 2, $q$First up$q$, $q$أول حاجة$q$, $q$Root$q$, $q$Root$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto"><div class="relative mx-auto w-[340px] h-[270px]"><div class="absolute left-[170px] top-[70px] origin-left rotate-[131.76deg] w-[112.6px] h-[3px] bg-gray-200 rounded-full"></div><div class="absolute left-[170px] top-[70px] origin-left rotate-[48.24deg] w-[112.6px] h-[3px] bg-gray-200 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[115.46deg] w-[93.0px] h-[3px] bg-gray-200 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[64.54deg] w-[93.0px] h-[3px] bg-gray-200 rounded-full"></div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[170px] top-[70px] w-14 h-14 rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d text-lg">A</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[95px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg opacity-40">B</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[245px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg opacity-40">C</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[55px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg opacity-40">D</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[135px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg opacity-40">E</div><div class="absolute -translate-x-1/2 left-[170px] top-[8px] flex flex-col items-center animate-bounce-subtle"><div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Root</div><div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div></div></div></div>$q$, $q$<p><code class="bg-brand-light text-brand-dark px-2 py-1 rounded-md text-sm font-mono border border-brand-purple/20">Root</code> is the node at the very top. It's the only node with <strong>no parent</strong>.</p><p>Every Tree has exactly one Root &mdash; it's where you always start when you want to reach any other node.</p>$q$, $q$<p><code class="bg-brand-light text-brand-dark px-2 py-1 rounded-md text-sm font-mono border border-brand-purple/20">Root</code> هو الـ Node اللي فوق خالص. هو الوحيد اللي مالوش <strong>Parent</strong>.</p><p>كل Tree ليه Root واحد بس &mdash; وهو نقطة البداية لما تيجي توصل لأي Node تاني.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (6, 3, $q$Why it matters$q$, $q$ليه محتاجينه$q$, $q$Why do we need a Root?$q$, $q$ليه محتاجين Root؟$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto"><div class="absolute -top-3 left-4 bg-white border border-gray-200 px-3 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">Root is missing</div><div class="relative mx-auto w-[340px] h-[270px]"><div class="absolute left-[95px] top-[154px] origin-left rotate-[115.46deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[64.54deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[170px] top-[70px] w-14 h-14 rounded-full border-2 border-dashed border-rose-400 bg-white text-rose-400 flex items-center justify-center font-bold text-lg">?</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[95px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">B</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[245px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">C</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[55px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">D</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[135px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">E</div></div></div>$q$, $q$<p>Without a reference to the Root, the other nodes still exist in memory &mdash; but you have no way to reach them.</p><p>It's the exact same problem as losing <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code> in a Linked List: the data is still there, it's just unreachable.</p>$q$, $q$<p>من غير مرجع للـ Root، باقي الـ Nodes لسه موجودة في الذاكرة &mdash; لكن مفيش طريقة توصلك ليها.</p><p>نفس مشكلة ما لو ضاع الـ <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Head</code> في Linked List بالظبط: البيانات لسه موجودة، بس مش قادر توصلها.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (6, 4, $q$Going down$q$, $q$وإحنا نازلين$q$, $q$Parent &amp; Child$q$, $q$Parent و Child$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto"><div class="relative mx-auto w-[340px] h-[270px]"><div class="absolute left-[170px] top-[70px] origin-left rotate-[131.76deg] w-[112.6px] h-[4px] bg-brand-purple rounded-full"></div><div class="absolute left-[170px] top-[70px] origin-left rotate-[48.24deg] w-[112.6px] h-[4px] bg-brand-purple rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[115.46deg] w-[93.0px] h-[3px] bg-gray-200 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[64.54deg] w-[93.0px] h-[3px] bg-gray-200 rounded-full"></div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[170px] top-[70px] w-14 h-14 rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d text-lg">A</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[95px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">B</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[245px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">C</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[55px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg opacity-40">D</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[135px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg opacity-40">E</div><div class="absolute -translate-x-1/2 left-[170px] top-[8px] flex flex-col items-center animate-bounce-subtle"><div class="bg-gray-900 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Parent</div><div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-gray-900 mt-0.5"></div></div><div class="absolute -translate-x-1/2 left-[95px] top-[92px] flex flex-col items-center animate-bounce-subtle"><div class="bg-teal-500 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Child</div><div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-teal-500 mt-0.5"></div></div><div class="absolute -translate-x-1/2 left-[245px] top-[92px] flex flex-col items-center animate-bounce-subtle"><div class="bg-teal-500 text-white font-bold text-[10px] px-2.5 py-1 rounded shadow-sm uppercase tracking-wider whitespace-nowrap">Child</div><div class="w-0 h-0 border-x-[6px] border-x-transparent border-t-[7px] border-t-teal-500 mt-0.5"></div></div></div></div>$q$, $q$<p><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A</code> is the <strong>parent</strong> of <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code> and <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">C</code>. And <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code> and <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">C</code> are <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A</code>'s <strong>children</strong>.</p><p>A node can have many children, but &mdash; other than the Root &mdash; every node has exactly <strong>one</strong> parent.</p>$q$, $q$<p><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A</code> هو الـ <strong>Parent</strong> بتاع <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code> و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">C</code>. و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code> و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">C</code> هما <strong>Children</strong> بتوع <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A</code>.</p><p>ممكن يكون للـ Node أكتر من Child، بس &mdash; غير الـ Root &mdash; كل Node ليه Parent واحد بس.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (6, 5, $q$Dead ends$q$, $q$آخر الطريق$q$, $q$Leaf Nodes$q$, $q$Leaf Nodes$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto"><div class="relative mx-auto w-[340px] h-[270px]"><div class="absolute left-[170px] top-[70px] origin-left rotate-[131.76deg] w-[112.6px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[170px] top-[70px] origin-left rotate-[48.24deg] w-[112.6px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[115.46deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[64.54deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[170px] top-[70px] w-14 h-14 rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d text-lg opacity-40">A</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[95px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg opacity-40">B</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[245px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-rose-400 bg-rose-50 text-rose-600 flex items-center justify-center font-bold node-3d text-lg ring-4 ring-rose-200">C</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[55px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-rose-400 bg-rose-50 text-rose-600 flex items-center justify-center font-bold node-3d text-lg ring-4 ring-rose-200">D</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[135px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-rose-400 bg-rose-50 text-rose-600 flex items-center justify-center font-bold node-3d text-lg ring-4 ring-rose-200">E</div></div></div>$q$, $q$<p>A <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Leaf</code> is a node with <strong>no children</strong> &mdash; a dead end. Here, <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">C</code>, <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">D</code>, and <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">E</code> are leaves.</p><p><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code> is not a leaf &mdash; it still has two children hanging off it.</p>$q$, $q$<p>الـ <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Leaf</code> هو Node مالوش <strong>Children خالص</strong> &mdash; يعني آخر الطريق. هنا <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">C</code> و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">D</code> و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">E</code> كلهم Leaves.</p><p><code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code> مش Leaf &mdash; لسه ليه Children.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (6, 6, $q$Measuring the tree$q$, $q$بنقيس الـ Tree إزاي$q$, $q$Height &amp; Levels$q$, $q$Height و Levels$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto"><div class="relative mx-auto w-[340px] h-[270px]"><div class="absolute left-[170px] top-[70px] origin-left rotate-[131.76deg] w-[112.6px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[170px] top-[70px] origin-left rotate-[48.24deg] w-[112.6px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[115.46deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute left-[95px] top-[154px] origin-left rotate-[64.54deg] w-[93.0px] h-[3px] bg-gray-300 rounded-full"></div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[170px] top-[70px] w-14 h-14 rounded-2xl border-[3px] border-brand-purple bg-brand-light text-brand-dark flex items-center justify-center font-bold node-3d text-lg">A</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[95px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">B</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[245px] top-[154px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">C</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[55px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-orange-400 bg-orange-50 text-orange-600 flex items-center justify-center font-bold node-3d text-lg">D</div><div class="absolute -translate-x-1/2 -translate-y-1/2 left-[135px] top-[238px] w-14 h-14 rounded-2xl border-[3px] border-teal-400 bg-teal-50 text-teal-600 flex items-center justify-center font-bold node-3d text-lg">E</div><div class="absolute -translate-y-1/2 left-1 top-[70px] bg-white border border-gray-200 px-2.5 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">Level 0</div><div class="absolute -translate-y-1/2 left-1 top-[154px] bg-white border border-gray-200 px-2.5 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">Level 1</div><div class="absolute -translate-y-1/2 left-1 top-[238px] bg-white border border-gray-200 px-2.5 py-1 rounded-md text-[10px] font-bold text-gray-500 uppercase tracking-wider shadow-sm">Level 2</div></div></div>$q$, $q$<p>Each row is a <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Level</code>, counted from the Root. <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A</code> is Level 0, <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code>/<code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">C</code> are Level 1, <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">D</code>/<code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">E</code> are Level 2.</p><p>The <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Height</code> of a Tree is its deepest level &mdash; the longest path from Root to a Leaf. This tree's height is <strong>2</strong>.</p>$q$, $q$<p>كل صف ده <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Level</code>، بنعده من الـ Root. <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">A</code> هو Level 0، و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">B</code>/<code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">C</code> هما Level 1، و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">D</code>/<code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">E</code> هما Level 2.</p><p>الـ <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Height</code> بتاع الـ Tree هو أعمق Level فيه &mdash; يعني أطول طريق من الـ Root لحد Leaf. الـ Tree ده Height بتاعه <strong>2</strong>.</p>$q$);
INSERT INTO lesson_slides (lesson_id, ordinal, kicker_en, kicker_ar, title_en, title_ar, visual, body_en, body_ar) VALUES (6, 7, $q$One Node = Data + Left + Right$q$, $q$Node واحدة = Data + Left + Right$q$, $q$The Node struct$q$, $q$الـ Node struct$q$, $q$<div class="visual-box bg-gray-50 border border-gray-200 rounded-xl p-5 sm:p-8 mb-6 shadow-sm relative overflow-x-auto"><div class="flex items-center justify-center gap-0 min-w-max py-2"><div class="flex rounded-2xl border-[3px] border-brand-purple overflow-hidden node-3d flex-shrink-0"><div class="w-14 h-14 sm:w-16 sm:h-16 bg-brand-light text-brand-dark flex items-center justify-center font-bold text-sm border-r-2 border-brand-purple">Data</div><div class="w-14 h-14 sm:w-16 sm:h-16 bg-white text-brand-dark flex items-center justify-center font-mono font-bold text-xs border-r-2 border-brand-purple">Left</div><div class="w-14 h-14 sm:w-16 sm:h-16 bg-white text-brand-dark flex items-center justify-center font-mono font-bold text-xs">Right</div></div></div></div><div class="code-cpp bg-[#1E1E2E] rounded-xl p-5 shadow-inner border border-gray-800 font-mono text-[13px] text-gray-300 leading-relaxed overflow-x-auto my-4" dir="ltr"><pre class="m-0"><code>struct Node {
    int data;
    Node* left;
    Node* right;
};</code></pre></div><div class="code-java bg-[#1E1E2E] rounded-xl p-5 shadow-inner border border-gray-800 font-mono text-[13px] text-gray-300 leading-relaxed overflow-x-auto my-4" dir="ltr"><pre class="m-0"><code>class Node {
    int data;
    Node left;
    Node right;
}</code></pre></div>$q$, $q$<p>Just like a Linked List node holds <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data</code> and <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code>, a Binary Tree node holds <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data</code> plus pointers to its two children: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Left</code> and <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Right</code>.</p><p>If a child doesn't exist, its pointer is simply <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code> &mdash; exactly like the end of a Linked List.</p>$q$, $q$<p>بالظبط زي ما الـ Linked List node بتحمل <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data</code> و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Next</code>، الـ Binary Tree node بتحمل <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Data</code> ومعاها Pointers لل-Children: <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Left</code> و <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">Right</code>.</p><p>لو مفيش Child موجود، الـ Pointer بتاعه بيبقى <code class="bg-white border border-gray-200 px-1.5 py-0.5 rounded font-mono text-sm">NULL</code> &mdash; بالظبط زي آخر الـ Linked List.</p>$q$);
